#!/usr/bin/env bash
#
# nexum-cleanup-notif-landing-bridge.sh
# =============================================================================
# Three independent cleanups (post bridge-fee revert; built on the CURRENT
# pre-fee bridge, so it does NOT reintroduce the reverted bridge fee).
#
# 1. NOTIFICATION PRUNING (7-day, READ-only)
#    - nexum-api/src/services/retention.ts   + pruneNotifications(wallet):
#      deletes a user's READ notifications older than 7 days. UNREAD are never
#      deleted. Per-user, best-effort, non-fatal (same contract as other pruners).
#    - nexum-api/src/routes/notifications.ts  calls it at the top of GET / so it
#      self-triggers per user (no cron needed).
#
# 2. LANDING PAGE - remove Settlements
#    - nexum-web/components/landing/LandingFeatures.tsx  removes the 'Settlements'
#      feature (the dashboard page no longer exists) + the now-unused BarChart3
#      import. Other 'settlement' copy elsewhere is unrelated and untouched.
#
# 3. BRIDGE 'Not started' orphan rows
#    - nexum-web/hooks/useBridge.ts  no longer creates the DB row on amount-entry;
#      the row is created at the BURN step (after approve), so typing an amount
#      and leaving creates NO row. Every real burn is still recorded for recovery.
#    - nexum-web/components/bridge/BridgeHistory.tsx  hides legacy orphan rows
#      (created/failed with no burn_tx) from Recent bridges, and relabels the
#      'failed' chip 'Failed' (a shown failed row now means a real burn that
#      failed, not one that never started).
#
# NO redeploy, NO contract change. Frontend + API only.
#
# DELIVERY STANDARD (v2): per-file base64 heredoc; decode + sha256 verify before
#   replace; backup once per file per run; idempotent; --revert to pristine.
#
# VERIFY AFTER:
#   cd nexum-api && npx tsc --noEmit
#   cd nexum-web && rm -rf .next && npx tsc --noEmit && npm run build
# =============================================================================
set -euo pipefail

find_root() {
  local d="$PWD"
  while [ "$d" != "/" ]; do
    if [ -d "$d/nexum-api/src" ] && [ -d "$d/nexum-web/hooks" ]; then echo "$d"; return 0; fi
    d="$(dirname "$d")"
  done
  if [ -d "$HOME/AfriFX/Nexum-main/nexum-api/src" ]; then echo "$HOME/AfriFX/Nexum-main"; return 0; fi
  if [ -d "$HOME/AfriFX/nexum-api/src" ]; then echo "$HOME/AfriFX"; return 0; fi
  return 1
}
ROOT="$(find_root)" || { echo "ERROR: repo root not found (needs nexum-api + nexum-web)."; exit 1; }
echo "Repo root: $ROOT"

STAMP="$(date +%Y%m%d-%H%M%S)"
MARKER=".nexum-cleanup-nlb.applied"
BACKUP_DIR="$ROOT/.nexum-cleanup-nlb-backups"

RET_PATH="$ROOT/nexum-api/src/services/retention.ts";               RET_SHA="8b110038ba8785360bfafc0bec26701eddc0e2f62517748d623ba65c560ab100"; RET_B64=""
NOT_PATH="$ROOT/nexum-api/src/routes/notifications.ts";             NOT_SHA="03a1e9e0d37c472d81e7e4a0925b4200213bbad15043d839d4dd887bc1ba7e73"; NOT_B64=""
LF_PATH="$ROOT/nexum-web/components/landing/LandingFeatures.tsx";   LF_SHA="d3e1fbd23aa70683de1aabf4663cf88d953622db13e601370b23b4db1377ee6e";  LF_B64=""
UB_PATH="$ROOT/nexum-web/hooks/useBridge.ts";                       UB_SHA="7da8c48117f2de528f7e5947d1c3522d396935bc7a2cd553187a0e4b1b333761";  UB_B64=""
BH_PATH="$ROOT/nexum-web/components/bridge/BridgeHistory.tsx";      BH_SHA="a420b88935a9773db21876587c5331f19db48577ad22e36b3db0a8bfaedff7fa";  BH_B64=""

restore_edit() { local base="$1" dest="$2" p; p="$(ls -1tr "$BACKUP_DIR"/"$base".* 2>/dev/null | head -n1 || true)"; if [ -n "${p:-}" ] && [ -f "$p" ]; then cp -f "$p" "$dest" && echo "restored $base"; else echo "no backup for $base"; fi; }

revert() {
  echo "== REVERT =="
  restore_edit "retention.ts"        "$RET_PATH"
  restore_edit "notifications.ts"    "$NOT_PATH"
  restore_edit "LandingFeatures.tsx" "$LF_PATH"
  restore_edit "useBridge.ts"        "$UB_PATH"
  restore_edit "BridgeHistory.tsx"   "$BH_PATH"
  rm -f "$BACKUP_DIR"/*.* 2>/dev/null || true
  rmdir "$BACKUP_DIR" 2>/dev/null || true
  rm -f "$ROOT/$MARKER"
  echo "revert complete."
}
if [ "${1:-}" = "--revert" ]; then revert; exit 0; fi

# Guard: make sure we are NOT about to overwrite a fee-version useBridge with the
# pre-fee one blindly - but since user reverted to pre-fee, warn only if fee code
# is present (means state changed since this was built).
if grep -q "bridgeWithFee" "$UB_PATH" 2>/dev/null; then
  echo "WARNING: current useBridge.ts contains bridgeWithFee (the reverted bridge"
  echo "  fee). This cleanup was built on the PRE-FEE bridge and will replace it"
  echo "  with the pre-fee version + the orphan-row fix. That is consistent with"
  echo "  your revert. Continuing."
fi

mkdir -p "$BACKUP_DIR"

write_edit() {
  local name="$1" path="$2" sha="$3" b64="$4"
  local tmp; tmp="$(mktemp)"
  printf '%s' "$b64" | base64 -d > "$tmp" || { echo "ERROR: decode failed for $name"; rm -f "$tmp"; exit 1; }
  local got; got="$(sha256sum "$tmp" | cut -d' ' -f1)"
  if [ "$got" != "$sha" ]; then echo "ERROR: checksum mismatch for $name"; echo "  expected $sha"; echo "  got      $got"; rm -f "$tmp"; exit 1; fi
  echo "  verified $name (sha256 ok)"
  [ -f "$path" ] && [ ! -f "$BACKUP_DIR/$(basename "$path").$STAMP" ] && cp -f "$path" "$BACKUP_DIR/$(basename "$path").$STAMP" && echo "  backed up $name"
  mv -f "$tmp" "$path"; echo "  wrote $path"
}

echo "== APPLY Nexum cleanups (notif prune + landing + bridge orphan) =="
write_edit "retention.ts"        "$RET_PATH" "$RET_SHA" "$RET_B64"
write_edit "notifications.ts"    "$NOT_PATH" "$NOT_SHA" "$NOT_B64"
write_edit "LandingFeatures.tsx" "$LF_PATH"  "$LF_SHA"  "$LF_B64"
write_edit "useBridge.ts"        "$UB_PATH"  "$UB_SHA"  "$UB_B64"
write_edit "BridgeHistory.tsx"   "$BH_PATH"  "$BH_SHA"  "$BH_B64"

touch "$ROOT/$MARKER"
echo
echo "== DONE =="
echo "Verify:"
echo "  cd $ROOT/nexum-api && npx tsc --noEmit"
echo "  cd $ROOT/nexum-web && rm -rf .next && npx tsc --noEmit && npm run build"
echo "Revert: bash $(basename "$0") --revert"
